'use strict';const D=JSON.parse(document.querySelector('#snapshot').textContent),B=D.brands,keys=Object.keys(B);const navs=['投資效益與 YoY','跨品牌預算配置','檔期投放節奏','Meta 與 Shopify 診斷','素材與廣告訴求','受眾與新客開發','商品與促銷洞察','下一檔期行動提案','資料來源與驗證','補充資訊｜台股與消費需求'];let active=0;const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));const fmt=(x,d=0)=>x==null||!Number.isFinite(x)?'—':x.toLocaleString('zh-TW',{minimumFractionDigits:d,maximumFractionDigits:d});const pct=(x,d=1)=>x==null?'—':fmt(x*100,d)+'%';const change=(a,b)=>b>0?(a/b-1):null;const diff=(x)=>x==null?'—':(x>0?'+':'')+pct(x);const div=(a,b)=>b>0&&a!=null?a/b:null;const sum=a=>a.reduce((s,x)=>s+(x??0),0);const spend=p=>p.m[0]+(p.g?.[0]??0);const roi=p=>div(p.s[4],spend(p));const roas=p=>div(p.m[7],p.m[0]);const all=()=>$('#brand').value==='ALL'?keys:[$('#brand').value];const comp=()=>$('#period').value;const per=(k,p='now')=>B[k].periods[p];const compareName=()=>comp()==='yoy'?'去年同期':'活動前同期';function evidence(i){const sheet=D.sources.dashboard,meta='https://adsmanager.facebook.com/adsmanager/manage/ads?act=',shops={DS:'https://admin.shopify.com/store/descente-tw/analytics',ASH:'https://admin.shopify.com/store/ash-golf-taiwan/analytics',CA:'https://admin.shopify.com/store/callaway-tw/analytics', '2XU':'https://admin.shopify.com/store/2xu-tw/analytics'};let labels=['帳戶花費、淨營收、目標ROI及同期比較','帳戶花費、淨營收、活動前同期','逐日花費、營收及活動日期','Meta帳戶原始指標與Shopify Taiwan Sessions','同名廣告群組及19組代表文案節錄','Dashboard新舊客訂單與Meta年齡性別','Shopify商品名稱／品類／Vendor及原始企劃','由前述證據推導的建議，不是已執行結果','原始查詢、資料範圍與公式','使用者提供台股交易日與 Shopify 每日淨營收'];return `<details class="evidence"><summary>資料依據與驗證入口 · ${labels[i]}</summary><p>資料截至 2026/11/22；快照 2026/11/25；台灣市場，TWD。<a href="${sheet}" target="_blank" rel="noopener noreferrer">Dashboard 原始表</a> · <a href="${D.sources.plan}" target="_blank" rel="noopener noreferrer">活動規劃</a></p>${all().map(k=>`<p>${B[k].name}：<a href="${meta+B[k].id}" target="_blank" rel="noopener noreferrer">Meta 帳戶</a> · <a href="${shops[k]}" target="_blank" rel="noopener noreferrer">Shopify Analytics</a> · ${B[k].start}–${B[k].end}（去年同日曆日期）</p>`).join('')}<p>完整公式與對帳請見第09章。來源連結需原本系統權限；不公開分享。</p></details>`}
function aggregate(ks,p='now'){let v={m:Array(8).fill(0),s:Array(9).fill(0),g:Array(5).fill(0)};for(let k of ks){let o=per(k,p);for(let x of ['m','s','g'])o[x]?.forEach((n,i)=>v[x][i]+=n)}return v}const cell=(v,cls='')=>`<td class="${cls}">${v}</td>`;function table(head,rows){return `<div class="table-wrap"><table><thead><tr>${head.map((h,i)=>`<th${i===0?' class="wrap"':''}>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map((c,i)=>cell(c,i===0?'wrap':'')).join('')}</tr>`).join('')}</tbody></table></div>`}const card=(t,h)=>`<div class="card"><h3>${t}</h3>${h}</div>`;const note=t=>`<div class="note">${t}</div>`;const ins=(t,h)=>`<div class="insight"><strong>${t}</strong>${h}</div>`;const page=(i,h)=>`<section class="section${active===i?' active':''}" id="s${i}"><div class="page-head"><div class="eyebrow small">CHAPTER ${String(i+1).padStart(2,'0')}</div><h2>${navs[i]}</h2><p>${['','比較各品牌規模、效率與資源調整方向','依活動階段與每日實際數據判讀','區分平台事件與實際網站購買','依實際廣告名稱彙總，觀察素材與訴求效率','分析實際購買結構與投放受眾','對照活動規劃，識別可驗證的商品機會','以 ROI 與可驗證結果決定下一步','原始資料、指標定義與未完成驗證','外部市場與消費需求：15個交易日探索性分析'][i]}</p></div>${h}${evidence(i)}</section>`;function kpi(t,v,s){return `<div class="kpi"><div class="small">${t}</div><strong>${v}</strong><span class="small">${s}</span></div>`}function bar(n,v,max,desc,target=null){return `<div class="barline"><b>${n}</b><div class="track${target!=null?' targetbar':''}" ${target!=null?`style="--target:${Math.min(target/max*100,99)}%"`:''}><div class="fill" style="width:${Math.min(Math.max(0,v/max*100),100)}%"></div></div><span>${desc}</span></div>`}

/* Shared offline SVG chart components. Values are derived from the snapshot, never independently stored. */
const palette={DS:'var(--accent)',ASH:'var(--series-2)',CA:'var(--series-3)','2XU':'var(--series-4)'};
const shortBrand=k=>({DS:'DESCENTE',ASH:'ASH GOLF',CA:'Callaway','2XU':'2XU TW'})[k];
const compact=v=>Math.abs(v)>=10000?fmt(v/10000,Math.abs(v)>=100000?0:1)+'萬':fmt(v,Math.abs(v)<10?1:0);
function legend(items){return `<div class="legend">${items.map(([n,c])=>`<span><i style="background:${c}"></i>${esc(n)}</span>`).join('')}</div>`}
function chartFrame(svg,label,foot='',wide=false){return `<figure class="viz"><div class="viz-scroll${wide?' wide':''}"><svg viewBox="0 0 760 300" role="img" aria-label="${esc(label)}" xmlns="http://www.w3.org/2000/svg">${svg}</svg></div>${foot?`<figcaption>${foot}</figcaption>`:''}</figure>`}
function columns(rows,series,{label='柱狀圖',format=compact,foot=''}={}){const W=760,H=300,L=66,R=18,T=30,BT=48,ph=H-T-BT,pw=W-L-R;let vals=rows.flatMap(r=>r.values).filter(Number.isFinite),hi=Math.max(0,...vals),lo=Math.min(0,...vals);hi=hi===0?1:hi*1.18;lo=lo<0?lo*1.1:0;const y=v=>T+(hi-v)/(hi-lo)*ph,group=pw/Math.max(1,rows.length),bw=Math.min(66,group*.72/series.length);let g='';for(let i=0;i<=4;i++){let v=lo+(hi-lo)*i/4;g+=`<line x1="${L}" y1="${y(v)}" x2="${W-R}" y2="${y(v)}" class="gridline"/><text x="${L-9}" y="${y(v)+4}" text-anchor="end" class="axis">${esc(format(v))}</text>`}g+=`<line x1="${L}" y1="${y(0)}" x2="${W-R}" y2="${y(0)}" class="baseline"/>`;rows.forEach((r,i)=>{let cx=L+group*(i+.5);r.values.forEach((v,j)=>{if(!Number.isFinite(v))return;let x=cx+(j-series.length/2)*bw+2,h=Math.abs(y(v)-y(0));g+=`<rect class="chart-mark" x="${x}" y="${Math.min(y(v),y(0))}" width="${Math.max(2,bw-4)}" height="${h}" rx="2" fill="${series[j][1]}"><title>${esc(r.label)} · ${esc(series[j][0])}：${esc(format(v))}</title></rect>`;if(rows.length*series.length<=16)g+=`<text x="${x+(bw-4)/2}" y="${v>=0?y(v)-7:y(v)+14}" text-anchor="middle" class="value-label">${esc(format(v))}</text>`});g+=`<text x="${cx}" y="${H-20}" text-anchor="middle" class="axis">${esc(r.label)}</text>`});return legend(series)+chartFrame(g,label,foot)}
function horizontal(rows,{label='排名',format=compact,foot='',color='var(--accent)'}={}){let max=Math.max(1,...rows.map(r=>Math.abs(r.value)));return `<figure class="viz ranked" role="group" aria-label="${esc(label)}">${rows.map(r=>`<div class="rankrow"><span>${esc(r.label)}</span><div class="ranktrack"><div class="rankfill" style="width:${Math.abs(r.value)/max*100}%;background:${r.color||color}"></div></div><b>${esc(format(r.value))}</b></div>`).join('')}${foot?`<figcaption>${foot}</figcaption>`:''}</figure>`}
function scatter(points,{label,xLabel,yLabel,xFmt=fmt,yFmt=fmt,xRef=null,yRef=null,quadrants=false,quadrantLabels=null,equalLine=false,detailsId='',foot='',legendItems=[],xMin=null,yMin=null}={}){if(!points.length)return '<div class="empty-viz">目前篩選條件無資料</div>';const W=760,H=300,L=76,R=32,T=30,BB=45,pw=W-L-R,ph=H-T-BB;let xs=points.map(p=>p.x),ys=points.map(p=>p.y);if(xRef!=null)xs.push(xRef);if(yRef!=null)ys.push(yRef);let xmin=xMin??Math.min(0,...xs),xmax=Math.max(...xs,1e-6),ymin=yMin??Math.min(0,...ys),ymax=Math.max(...ys,1e-6);xmax+=(xmax-xmin||1)*.12;if(quadrants&&!equalLine)xmax=Math.max(xmax,1.30);ymax+=(ymax-ymin||1)*.15;if(ymin<0&&yMin==null)ymin-=(ymax-ymin)*.07;if(equalLine){xmax=Math.max(1,Math.ceil(xmax*2)/2);ymax=Math.max(2,Math.ceil(ymax*2)/2);}const x=v=>L+(v-xmin)/(xmax-xmin)*pw,y=v=>T+(ymax-v)/(ymax-ymin)*ph;let g='';if(quadrants&&xRef!=null&&yRef!=null){let rx=x(xRef),ry=y(yRef);g+=`<rect x="${L}" y="${T}" width="${rx-L}" height="${ry-T}" fill="var(--accent-l)"/><rect x="${rx}" y="${T}" width="${W-R-rx}" height="${ry-T}" fill="var(--quadrant-positive)"/><rect x="${L}" y="${ry}" width="${rx-L}" height="${H-BB-ry}" fill="var(--quadrant-negative)"/><rect x="${rx}" y="${ry}" width="${W-R-rx}" height="${H-BB-ry}" fill="var(--paper)"/>`;for(let [xx,yy,tt] of [[L+7,T+13,quadrantLabels?.[0]??'成長／未達標'],[rx+7,T+13,quadrantLabels?.[1]??'成長／達標'],[L+7,H-BB-7,quadrantLabels?.[2]??'衰退／未達標'],[rx+7,H-BB-7,quadrantLabels?.[3]??'衰退／達標']])g+=`<text x="${xx}" y="${yy}" class="quadrant-label">${tt}</text>`}for(let i=0;i<=4;i++){let a=xmin+(xmax-xmin)*i/4,b=ymin+(ymax-ymin)*i/4;g+=`<line x1="${x(a)}" y1="${T}" x2="${x(a)}" y2="${H-BB}" class="gridline"/><line x1="${L}" y1="${y(b)}" x2="${W-R}" y2="${y(b)}" class="gridline"/><text x="${x(a)}" y="${H-BB+17}" text-anchor="middle" class="axis">${esc(xFmt(a))}</text><text x="${L-8}" y="${y(b)+4}" text-anchor="end" class="axis">${esc(yFmt(b))}</text>`}if(xRef!=null)g+=`<line x1="${x(xRef)}" y1="${T}" x2="${x(xRef)}" y2="${H-BB}" class="reference"/><text x="${x(xRef)-4}" y="${T-6}" text-anchor="end" class="axis">${esc(xFmt(xRef))}</text>`;if(yRef!=null)g+=`<line x1="${L}" y1="${y(yRef)}" x2="${W-R}" y2="${y(yRef)}" class="reference"/>`;if(equalLine){let a=Math.max(xmin,ymin),b=Math.min(xmax,ymax);if(a<b)g+=`<line x1="${x(a)}" y1="${y(a)}" x2="${x(b)}" y2="${y(b)}" stroke="var(--accent)" stroke-dasharray="6 4" stroke-width="1.7"/><text x="${x(b)-4}" y="${y(b)-7}" text-anchor="end" class="axis">同幅成長線</text>`}let maxSize=Math.max(1,...points.map(p=>p.size||0));const sorted=[...points].sort((a,b)=>b.size-a.size);sorted.forEach((p,i)=>{let r=Math.max(3,Math.sqrt((p.size||0)/maxSize)*22),cx=x(p.x),cy=y(p.y),descr=`${p.label}｜${xLabel} ${xFmt(p.x)}｜${yLabel} ${yFmt(p.y)}｜花費 NT$ ${fmt(p.size)}${p.detail?'｜'+p.detail:''}`;g+=`<circle class="chart-mark bubble" cx="${cx}" cy="${cy}" r="${r}" fill="${p.color}" fill-opacity=".78" stroke="white" stroke-width="1.2" tabindex="0" role="button" aria-label="${esc(descr)}" ${detailsId?`data-detail="${esc(descr)}" data-target="${detailsId}"`:''}><title>${esc(descr)}</title></circle>`;if(quadrants){let align=cx>W-R-90?'end':'start',xx=cx+(align==='end'?-r-3:r+3);g+=`<text x="${xx}" y="${cy+4}" text-anchor="${align}" class="bubble-label">${esc(p.label)}</text>`}});g+=`<text x="${L+pw/2}" y="${H-5}" text-anchor="middle" class="axis-title">${esc(xLabel)}</text><text transform="translate(14 ${T+ph/2}) rotate(-90)" text-anchor="middle" class="axis-title">${esc(yLabel)}</text>`;return legend(legendItems)+chartFrame(g,label,foot,true)+(detailsId?`<div class="chart-detail" id="${detailsId}" aria-live="polite">點選氣泡或以鍵盤選取，即可查看詳細數據。</div>`:'')}
function funnelChart(values,labels){let W=760,H=300,stageW=[640,520,400,280],g='';values.forEach((v,i)=>{let cy=14+i*70,top=stageW[i],bottom=top-65,x1=(W-top)/2,x2=(W-bottom)/2;g+=`<path d="M${x1} ${cy} H${W-x1} L${W-x2} ${cy+60} H${x2} Z" fill="${['var(--accent)','var(--accent-hover)','var(--series-2)','var(--series-4)'][i]}" class="chart-mark"><title>${esc(labels[i])}：${fmt(v)} / ${pct(v/values[0],3)}</title></path><text x="380" y="${cy+22}" text-anchor="middle" class="funnel-label">${esc(labels[i])}</text><text x="380" y="${cy+45}" text-anchor="middle" class="funnel-number">${fmt(v)} · ${pct(v/values[0],3)}</text>`});return chartFrame(g,'Shopify 轉換漏斗','漏斗面積為階段示意，非數值比例；百分比以全部 Sessions 為分母。')}
function segmented(id){let el=$('#'+id);if(!el)return;let box=document.createElement('div');box.className='segmented';box.setAttribute('role','group');box.setAttribute('aria-label',el.parentElement.textContent.trim());box.innerHTML=[...el.options].map(o=>`<button type="button" data-value="${esc(o.value)}" aria-pressed="${o.value===el.value}">${esc(o.textContent)}</button>`).join('');el.classList.add('select-hidden');el.parentElement.after(box);const sync=()=>box.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',b.dataset.value===el.value));box.addEventListener('click',e=>{let b=e.target.closest('button');if(b){el.value=b.dataset.value;el.dispatchEvent(new Event('change',{bubbles:true}));sync()}});el.addEventListener('change',sync)}

function rev(){let ks=all(),a=aggregate(ks),c=aggregate(ks,comp()),y=comp()==='yoy';let total=spend(a);return page(0,`<div class="executive"><div class="eyebrow">EXECUTIVE SUMMARY</div><h2>廣告投資與經營決策摘要</h2><p>聚焦 ROI、轉換效率及下一檔期投放策略。${ks.length===4?'四品牌訂單規模同比成長，但營收成長較慢。':''}</p></div><div class="kpis">${kpi('淨營收','NT$ '+fmt(a.s[4]),compareName()+' '+diff(change(a.s[4],c.s[4])))}${kpi('已記錄總廣告費','NT$ '+fmt(total),compareName()+' '+diff(change(total,spend(c))))}${kpi('ROI',fmt(roi(a),2)+'×',compareName()+' '+diff(change(roi(a),roi(c))))}${kpi('Meta ROAS（參考）',fmt(roas(a),2)+'×',compareName()+' '+diff(change(roas(a),roas(c))))}${kpi('實際訂單',fmt(a.s[0]),compareName()+' '+diff(change(a.s[0],c.s[0])))}${kpi('Meta 花費占比',pct(div(a.m[0],total)),'其餘為已記錄 Google 花費')}${kpi('廣告費用率',pct(div(total,a.s[4]),2),compareName()+' '+(div(spend(c),c.s[4])==null?'—':pct(div(spend(c),c.s[4]),2))+'（已記錄花費/淨營收）')}${kpi('淨營收／單',fmt(div(a.s[4],a.s[0])),'非 Shopify 原生 AOV')}</div>`+card('淨營收｜2025 vs 2026',columns(ks.map(k=>({label:shortBrand(k),values:[per(k,'yoy').s[4],per(k).s[4]]})),[['2025 同期','var(--series-prev)'],['2026 雙11','var(--accent)']],{label:'兩年淨營收比較',foot:'單位：新台幣；各品牌依原定等日曆期間。'}))+card('營收與 Meta 成效同比',table(['品牌','2025 淨營收','2026 淨營收','營收 YoY','Meta 花費 YoY','Meta ROAS YoY'],ks.map(k=>{let p=per(k),q=per(k,'yoy');return [B[k].name,fmt(q.s[4]),fmt(p.s[4]),diff(change(p.s[4],q.s[4])),diff(change(p.m[0],q.m[0])),diff(change(roas(p),roas(q)))]})))+card('整體廣告投資效率｜兩年同期',columns(ks.map(k=>({label:shortBrand(k),values:[roi(per(k,'yoy')),roi(per(k))]})),[['2025 同期','var(--series-prev)'],['2026 雙11','var(--accent)']],{label:'整體 ROI 同比',format:v=>fmt(v,2)+'×',foot:'ROI = Shopify 淨營收 / (Meta + Google 已記錄花費)。2025 Google 為人工提供；ASH、CA 本期 Google 無列暫算。'})+table(['品牌','2025 Meta','2025 Google¹','2025 總花費','2026 總花費²','總花費 YoY','2025 ROI','2026 ROI','ROI YoY'],ks.map(k=>{let p=per(k),q=per(k,'yoy');return [B[k].name,fmt(q.m[0]),fmt(q.g[0],2),fmt(spend(q),2),fmt(spend(p),2),diff(change(spend(p),spend(q))),fmt(roi(q),2),fmt(roi(p),2),diff(change(roi(p),roi(q)))]}))+note('¹ 使用者提供之期間總額，未經 Google Ads 後台獨立核對。² ASH、Callaway 本期 Google 無列，暫按已記錄值。'))+card('跨平台廣告花費配置｜2025 vs 2026',table(['品牌／年度','Meta 花費','Google 花費','總花費','Meta 占比','Google 占比'],ks.flatMap(k=>['yoy','now'].map(t=>{let p=per(k,t);return [B[k].name+' / '+(t==='yoy'?'2025':'2026'),fmt(p.m[0],2),p.g?fmt(p.g[0],2):'無列',fmt(spend(p),2),pct(p.m[0]/spend(p)),p.g?pct(p.g[0]/spend(p)):'—']}))))+card('各品牌目標與實績',table(['品牌','本期淨營收','Meta 花費','Google 已記錄','ROI','目標 ROI','ROI達成','營收 '+compareName(),'總廣告費 '+compareName(),'ROI '+compareName()],ks.map(k=>{let b=B[k],p=per(k),q=per(k,comp());return [b.name,fmt(p.s[4]),fmt(p.m[0]),p.g?fmt(p.g[0]):'無列＊',`<b class="${roi(p)>=b.target?'good':'bad'}">${fmt(roi(p),2)}×</b>`,fmt(b.target,2),pct(roi(p)/b.target),diff(change(p.s[4],q.s[4])),diff(change(spend(p),spend(q))),diff(change(roi(p),roi(q)))]}))+note('＊ASH GOLF、Callaway 本期與前期 Google 無資料列，依 Dashboard 已記錄花費暫算 ROI；尚未證實實際零投放。2025 Google 花費由使用者提供，未獨立對帳；轉換定義不一致，去年 Google 轉換指標不列入比較。'))+card('ROI 與目標差距',ks.map(k=>{let b=B[k];return bar(b.name,roi(per(k)),Math.max(17,b.target,roi(per(k))),fmt(roi(per(k)),2)+'×',b.target)}).join('')+'<p class="small">深線為各品牌目標 ROI；比例尺度共用 17× 起。</p>')+card('管理層重點',ks.map(k=>ins(B[k].name,({'DS':'ROI 6.33 達標但僅高 0.03；整體花費同比 +7.7%、營收 +5.1%，ROI 同比 -2.4%，效率略降。','ASH':'ROI 7.97 低於 9；淨營收同比 +39.2%，整體花費 +20.1%，整體 ROI 同比 +16.0%（本期 Google 無列暫算）；訂單增幅高於營收，仍應改善客單。','CA':'ROI 3.00 對比目標 16.7，淨營收同比 -90.7%、整體花費 -67.7%，整體 ROI 同比 -71.3%（本期 Google 無列暫算）；Shopify確認非漏數；優先評估商品型號、可購買規格與需求匹配。SKU不足為待驗證因素。','2XU':'淨營收同比 +141.6%，ROI 5.61 低於 7.16；整體花費同比 +62.5%，ROI 同比 +48.7%，較前期 ROI +6.3%；仍須改善目標差距。'})[k])).join('')))}

function budget(){let ks=all(),a=aggregate(keys);return page(1,card('廣告投入與營收成長四象限',scatter(ks.map(k=>{let p=per(k),q=per(k,'yoy');return {label:shortBrand(k),x:change(spend(p),spend(q)),y:change(p.s[4],q.s[4]),size:spend(p),color:palette[k],detail:'ROI '+fmt(roi(q),2)+' → '+fmt(roi(p),2)+'（'+diff(change(roi(p),roi(q)))+'）'}}),{label:'整體廣告花費與淨營收 YoY 四象限',xLabel:'整體廣告花費 YoY',yLabel:'淨營收 YoY',xFmt:v=>pct(v,0),yFmt:v=>pct(v,0),xRef:0,yRef:0,quadrants:true,quadrantLabels:['減少投入／營收成長','增加投入／營收成長','減少投入／營收衰退','增加投入／營收衰退'],equalLine:true,xMin:-1,yMin:-1,detailsId:'budgetDetail',foot:'兩軸均為（2026 / 2025 − 1）×100%；氣泡面積代表2026已記錄廣告費。斜虛線為營收及投入變動相等；上方代表整體 ROI 改善、下方代表下降。2025 Google 花費為人工提供；ASH、CA 本期無列暫算。'})+table(['品牌','總花費 YoY','營收 YoY','成長率差距（百分點）','2025 ROI','2026 ROI','ROI YoY'],ks.map(k=>{let p=per(k),q=per(k,'yoy'),x=change(spend(p),spend(q)),y=change(p.s[4],q.s[4]);return [B[k].name,diff(x),diff(y),(y-x>0?'+':'')+fmt((y-x)*100,1),fmt(roi(q),2),fmt(roi(p),2),diff(change(roi(p),roi(q)))]}))+note('2XU、ASH GOLF 營收增幅高於整體花費增幅；DESCENTE 略低，Callaway 營收減幅大於花費減幅。此為同期經營效率比較，不能證明廣告增量或直接推導跨品牌預算移轉。'))+card('花費／淨營收占比',columns(ks.map(k=>({label:shortBrand(k),values:[spend(per(k))/spend(a),per(k).s[4]/a.s[4]]})),[['廣告花費','var(--accent)'],['淨營收','var(--series-4)']],{label:'花費與營收占比柱狀比較',format:v=>pct(v,1),foot:'四品牌總體為分母；Google 缺列採已記錄值。'}))+card('花費與淨營收分配',table(['品牌','花費','花費占比','淨營收占比','日均花費','ROI','目標差距','Meta ROAS','Google ROAS'],ks.map(k=>{let p=per(k),b=B[k];return[b.name,fmt(spend(p)),pct(spend(p)/spend(a)),pct(p.s[4]/a.s[4]),fmt(spend(p)/b.days),fmt(roi(p),2),fmt(roi(p)-b.target,2),fmt(roas(p),2),p.g?fmt(div(p.g[1],p.g[0]),2):'—']}))+ks.map(k=>bar(B[k].name,spend(per(k)),spend(a),pct(spend(per(k))/spend(a)))).join(''))+card('活動前同期比較',table(['品牌','廣告費變化','淨營收變化','活動前 ROI','雙11 ROI'],ks.map(k=>{let p=per(k),q=per(k,'prev');return [B[k].name,diff(change(spend(p),spend(q))),diff(change(p.s[4],q.s[4])),fmt(roi(q),2),fmt(roi(p),2)]}))+note('前期包含部分搶先購，不是純無促銷對照。Google缺列仍以已記錄值暫算。'))+card('資源調整建議',ks.map(k=>ins(B[k].name,({'DS':'維持基礎投放，調整正檔與目錄配置。優先測試可維持 ROI 的素材，再分段擴量。','ASH':'保留高效率目錄與倒數素材，降低只帶來低客單的投放比重。先驗證訂單價值改善。','CA':'優先評估商品豐富度與需求匹配；比較兩年可購買型號、規格SKU、價格帶及導購頁商品數，據此調整資源。歷史可購買SKU數未取得，不能認定因果。','2XU':'保留成長來源，控制倒數期效率；Google 已記錄 ROAS 9.70、花費占比 18.5%，先查增量與歸因重疊再調渠道。'})[k])).join(''))+note('不以 ROAS 直接決定預算。現有資料為觀察性結果，無增量實驗；跨品牌 ROI、商品組合與需求不同，不推算固定預算移轉百分比。'))}

function dayRows(ks){let dates=[...new Set(ks.flatMap(k=>B[k].daily.map(r=>r.date)))].sort();return dates.map(date=>{let a=ks.map(k=>B[k].daily.find(r=>r.date===date)).filter(Boolean);let known=a.filter(r=>r.net!=null);return {date,net:known.length?sum(known.map(r=>r.net)):null,cost:sum(a.map(r=>r.meta+(r.google??0))),meta:sum(a.map(r=>r.meta)),orders:known.length?sum(known.map(r=>r.orders)):null,partial:known.length!==a.length}})}function pace(){let ks=all(),r=dayRows(ks);return page(2,card('各階段 ROI 比較',columns(ks.map(k=>({label:shortBrand(k),values:['提前','正檔','倒數','延長'].map(n=>{let phase=B[k].phases.find(x=>x[0].includes(n));if(!phase)return null;let a=B[k].daily.slice(phase[1],phase[2]+1);return div(sum(a.map(r=>r.net)),sum(a.map(r=>r.meta+(r.google??0))))})})),[['提前','var(--series-prev)'],['正檔','var(--accent)'],['倒數','var(--series-2)'],['延長','var(--series-4)']],{label:'階段 ROI 柱狀圖',format:v=>fmt(v,1)+'×',foot:'各品牌依實際階段；無該階段留空，不視為零。'}))+card('檔期階段',table(['品牌／階段','日期','天數','淨營收','廣告費','日均花費','日均淨營收','ROI','銷售日覆蓋'],ks.flatMap(k=>B[k].phases.map(([n,s,e])=>{let a=B[k].daily.slice(s,e+1),net=sum(a.map(r=>r.net)),cost=sum(a.map(r=>r.meta+(r.google??0)));return[B[k].name+' / '+n,a[0].date.slice(5)+'–'+a.at(-1).date.slice(5),a.length,fmt(net),fmt(cost),fmt(cost/a.length),fmt(net/a.length),fmt(div(net,cost),2),a.filter(r=>r.net!=null).length+'/'+a.length]})))+ks.map(k=>ins(B[k].name,({'DS':'11/18 起倒數；正檔至倒數日均花費減少9.6%，日均營收增加30.5%，ROI 由5.59升至8.07（+44.3%）。','ASH':'正檔 ROI 7.49，倒數 8.66，延長 12.63；延長期只有兩天，不直接推論可大幅擴量。','CA':'11/22 是階段截止，不是完整結案；Shopify 已直接驗證其餘12天確實零訂單、零淨營收，並保留11/6負淨營收。','2XU':'正檔至倒數日均花費增加2.3%，日均營收下降58.5%，ROI 由6.38降至2.59（-59.4%）；應對照當期素材及網站轉換。'})[k])).join(''))+card('每日原始數據（供查核）',`<div class="controls"><label>起日 <input type="date" id="from" value="${r[0].date}" min="${r[0].date}" max="${r.at(-1).date}"></label><label>迄日 <input type="date" id="to" value="${r.at(-1).date}" min="${r[0].date}" max="${r.at(-1).date}"></label></div><div id="trendTable"></div>`)+note('四品牌起始日不同，總覽逐日按各品牌分析期間加總；10/30–11/1 僅 DESCENTE。日級缺列保留空值；跨品牌部分缺列日的營收與 ROI 是已記錄值。'))}
function trendUpdate(){let r=dayRows(all()).filter(x=>x.date>=$('#from').value&&x.date<=$('#to').value);$('#trendTable').innerHTML=r.length?`<details><summary>展開每日數據（${r.length}天）</summary>${table(['日期','淨營收','總花費','訂單','ROI','資料狀態'],r.map(x=>[x.date,fmt(x.net),fmt(x.cost),fmt(x.orders),fmt(div(x.net,x.cost),2),x.partial?'銷售缺列／部分':'已記錄']))}</details>`:'<p class="small">無資料，請調整日期。</p>'}
function funnel(){let ks=all();return page(3,card('4.1 Meta 廣告效率｜同比切換',`<div class="controls"><label>顯示 <select id="metaMode"><option value="now">2026 雙11</option><option value="yoy">2025 同期</option><option value="delta">YoY 變化</option></select></label></div><div class="controls"><label>圖表指標 <select id="metaChartMetric"><option value="0">CPM</option><option value="1">CTR</option><option value="2">CPC</option><option value="3">CPA</option><option value="4">ROAS</option></select></label></div><div id="metaChart"></div><div id="metaCompare"></div>`)+card('4.2 Shopify 台灣站內漏斗｜四品牌直接驗證',`<div class="controls"><label>品牌 <select id="funnelBrand">${ks.map(k=>`<option value="${k}">${B[k].name}</option>`).join('')}</select></label><label>期間 <select id="funnelYear"><option value="now">2026 雙11</option><option value="yoy">2025 同期</option></select></label></div><div id="funnelVisual"></div>`)+card('Meta 事件明細',table(['品牌／期間','曝光','CPM','連結點擊','CTR','CPC','落地頁瀏覽','加購事件','結帳事件','歸因購買','CPA','購買／點擊'],ks.flatMap(k=>['now','yoy'].map(p=>{let m=per(k,p).m;return[B[k].name+' / '+(p==='now'?'本期':'去年同期'),fmt(m[1]),fmt(div(m[0]*1000,m[1]),2),fmt(m[2]),pct(div(m[2],m[1]),2),fmt(div(m[0],m[2]),2),fmt(m[3]),fmt(m[4]),fmt(m[5]),fmt(m[6]),fmt(div(m[0],m[6]),2),pct(div(m[6],m[2]),2)]})))+note('Meta 事件並非同一批使用者的逐步漏斗；購買／點擊是事件比率，不是網站 CVR。'))+card('Shopify 實際訂單及淨客單',table(['品牌／期間','商品銷售額','折扣','退貨','淨營收','訂單','淨營收／單'],ks.flatMap(k=>['now','yoy'].map(p=>{let s=per(k,p).s;return [B[k].name+' / '+(p==='now'?'本期':'去年同期'),...s.slice(1,5).map(x=>fmt(x)),fmt(s[0]),fmt(div(s[4],s[0]))]})))+'<p class="small">淨營收／訂單不等同 Shopify 原生 AOV。</p>')+card('兩年漏斗數據',table(['品牌／期間','Sessions','加購','加購率','結帳','完成購買','CVR','加購→結帳','結帳→購買'],ks.flatMap(k=>['now','yoy'].map(p=>{let a=B[k].sessions[p];return[B[k].name+' / '+(p==='now'?'本期':'去年同期'),fmt(a[0]),fmt(a[1]),pct(div(a[1],a[0]),2),fmt(a[2]),fmt(a[3]),pct(div(a[3],a[0]),3),pct(div(a[2],a[1]),1),pct(div(a[3],a[2]),1)]})))+'<p class="small">Shopify session_country=Taiwan，銷售採 billing_country=Taiwan；不同維度，購買Sessions不等於訂單數。</p>')+card('網站購買轉換率｜兩年同比',columns(ks.map(k=>({label:shortBrand(k),values:['yoy','now'].map(p=>div(B[k].sessions[p][3],B[k].sessions[p][0]))})),[['2025 同期','var(--series-prev)'],['2026 雙11','var(--accent)']],{label:'Shopify CVR 比較',format:v=>pct(v,3),foot:'完成購買 Sessions / 全部 Sessions。'}))+card('CVR 變化與原訂目標',table(['品牌','去年同期','本期','YoY','原訂 CVR 目標'],ks.map(k=>{let q=B[k].sessions,v=p=>div(q[p][3],q[p][0]);return[B[k].name,pct(v('yoy'),3),pct(v('now'),3),diff(change(v('now'),v('yoy'))),k==='2XU'?'0.60%｜已達':'未提供']})))+card('診斷結論',ks.map(k=>ins(B[k].name,({'DS':'Sessions同比 +20.6%，但CVR從0.591%降至0.458%（-22.5%），實際訂單減少16單。淨售出件數1249對比1644（-24.0%）；退貨金額改善支撐淨營收，需改善導購效率。','ASH':'網站 CVR 同比 +26.8%，Sessions +146.4%；訂單增加，但淨營收／單由去年約11,247降至5,220。改善商品結構與客單優先於只增加流量。','CA':'Shopify已證實12天零訂單零淨營收。同比加購率與CVR明顯下降；先驗證可購買型號、SKU選擇與導購需求匹配，再查購物車／結帳流程。歷史SKU數不足尚未證實。','2XU':'CVR 0.864%超越0.60%原訂目標；同比仍-10.8%。Sessions同比+178.6%，營收成長主要伴隨流量擴張；提高效率需兼顧加購、商品與跨媒體成本。'})[k])).join('')))}

function metaMetrics(m){return [div(m[0]*1000,m[1]),div(m[2],m[1]),div(m[0],m[2]),div(m[0],m[6]),div(m[7],m[0])]}
function metaUpdate(){let mode=$('#metaMode').value;$('#metaCompare').innerHTML=table(['品牌','CPM','連結CTR','CPC','CPA','ROAS'],all().map(k=>{let a=metaMetrics(per(k).m),b=metaMetrics(per(k,'yoy').m);return[B[k].name,...a.map((v,i)=>{if(mode==='delta'){let x=change(v,b[i]),good=(i===1||i===4)?x>=0:x<=0;return `<span class="${good?'good':'bad'}">${diff(x)}</span>`}let z=(mode==='yoy'?b:a)[i];return i===1?pct(z,2):fmt(z,i===3?0:2)})]}))+note('YoY = 本期 / 去年同期 - 1；CPM、CPC、CPA下降及CTR、ROAS上升以綠色表示，僅代表一般效率方向。');metaChartUpdate()}
function funnelUpdate(){let b=B[$('#funnelBrand').value],p=$('#funnelYear').value,a=b.sessions[p],y=b.sessions.yoy,c=b.sessions.now;let labels=['網站 Sessions','加購 Sessions','結帳 Sessions','購買 Sessions'];$('#funnelVisual').innerHTML=funnelChart(a,labels)+table(['指標','去年同期','本次雙11','YoY'],labels.map((t,i)=>{let x=i?c[i]/c[0]:c[i],z=i?y[i]/y[0]:y[i];return[i?t.replace(' Sessions','率'):t,i?pct(z,3):fmt(z),i?pct(x,3):fmt(x),diff(change(x,z))]}))+note('以全部Sessions為各階段分母；購買Sessions不等於訂單。此章僅比較本次與去年。')}

function metaChartUpdate(){let i=+$('#metaChartMetric').value,mode=$('#metaMode').value,labels=['CPM','CTR','CPC','CPA','ROAS'];let f=v=>i===1?pct(v,2):i===4?fmt(v,2)+'×':'$'+fmt(v,i===3?0:2);let rows=all().map(k=>{let a=metaMetrics(per(k).m)[i],b=metaMetrics(per(k,'yoy').m)[i];return{label:shortBrand(k),values:mode==='delta'?[change(a,b)]:[b,a]}});$('#metaChart').innerHTML=columns(rows,mode==='delta'?[[labels[i]+' YoY','var(--accent)']]:[['2025 同期','var(--series-prev)'],['2026 雙11','var(--accent)']],{label:labels[i]+' 年度比較',format:mode==='delta'?v=>pct(v,1):f,foot:mode==='delta'?'相對變化率 = 2026 / 2025 - 1。':'並列顯示兩年數據；表格可單獨切換期間。'})}

function creativeRows(){return all().flatMap(k=>B[k].ads.map(a=>({...a,brand:k,roas:div(a.v[4],a.v[0]),cpa:div(a.v[0],a.v[3]),ctr:div(a.v[2],a.v[1])})))}function creative(){let a=creativeRows(),tags=[...new Set(a.map(x=>x.tag))].sort();return page(4,card('素材成效探索',`<div class="controls"><label>訴求 <select id="tag"><option value="ALL">全部</option>${tags.map(t=>`<option>${esc(t)}</option>`).join('')}</select></label><label>排序 <select id="sort"><option value="spend">花費</option><option value="value">購買價值</option><option value="roas">ROAS</option><option value="cpa">CPA（低→高）</option><option value="orders">購買次數</option><option value="ctr">CTR</option></select></label><label>最低花費 <select id="minsp"><option value="0">不限</option><option value="1000" selected>1,000</option><option value="5000">5,000</option><option value="10000">10,000</option></select></label><input id="search" placeholder="搜尋廣告名稱"></div><div class="controls"><label>氣泡圖橫軸 <select id="bubbleX"><option value="ctr">連結 CTR</option><option value="orders">歸因購買次數</option></select></label></div><div id="adBubble"></div><div id="adTable"></div><p class="small">預設最低花費 NT$1,000，避免小額極端值壓縮圖表；選「不限」可檢視全部同名素材。依同名廣告彙總，不等同單一 Creative ID。訴求以名稱初步分類，非人工逐張審核；低樣本高 ROAS 不代表可擴量。</p>`)+card('訴求分類成效',`<div id="tagTable"></div>`)+card('值得驗證的素材策略',all().map(k=>ins(B[k].name,({'DS':'新品目錄 17.41 萬花費、ROAS 6.59；Sport 正檔套框花費 15.53 萬、ROAS 5.51。第一件換季 ROAS 12.58（40 次購買），值得擴展情境素材測試。','ASH':'Callaway 11.11 ROAS 11.28、全館目錄 10.66、最後倒數 10.38；主活動 SALE 6.20、PAYNTR 5.29。建議按商品與導購策略拆分。','CA':'雙11_clubs26 ROAS 2.40，sale2611all 1.41；其餘兩款舊廣告未歸因購買。先修正導購及商品訴求，不以 CTR 單獨選贏家。','2XU':'主 BN02 佔 Meta 花費約 49.9%，ROAS 7.35；服飾折扣 7.12。倒數 01-2 ROAS 4.23，應改善倒數訴求與投放時機。'})[k])).join(''))+card('原始廣告入口',all().map(k=>`<div class="metricline"><b>${B[k].name}</b><a target="_blank" rel="noopener noreferrer" href="https://adsmanager.facebook.com/adsmanager/manage/ads?act=${B[k].id}">開啟 Meta 廣告管理員 ↗</a></div>`).join('')+card('代表素材原始文案與廣告證據（19組）',all().map(k=>'<h4>'+B[k].name+'</h4>'+table(['名稱／原始標題','原文節錄','格式','人工訴求分類','來源'],B[k].creative_samples.map(a=>[esc(a[0])+'<br><span class="small">'+esc(a[3])+'</span>',esc(a[4]).replaceAll('\n','<br>'),esc(a[5]),esc(a[6]),'<a target="_blank" rel="noopener noreferrer" href="https://adsmanager.facebook.com/adsmanager/manage/ads?act='+B[k].id+'&selected_ad_ids='+a[1]+'">檢視廣告</a>']))).join(''))+note('代表素材依單支花費篩選後取原始標題及內文節錄；同名群組可能有多版本。SHARE為Meta物件類型，無法據此斷定單圖或影片。其他素材及完整原圖仍需驗證；素材訴求非因果結論。')))}function adUpdate(){let a=creativeRows(),tag=$('#tag').value,s=$('#sort').value,min=+$('#minsp').value,q=$('#search').value.toLowerCase();let v={spend:x=>x.v[0],value:x=>x.v[4],roas:x=>x.roas??-1,cpa:x=>x.cpa??Infinity,orders:x=>x.v[3],ctr:x=>x.ctr??-1}[s];let filtered=a.filter(x=>(tag==='ALL'||x.tag===tag)&&x.v[0]>=min&&x.name.toLowerCase().includes(q)).sort((a,b)=>s==='cpa'?v(a)-v(b):v(b)-v(a));$('#adBubble').innerHTML=scatter(filtered.filter(x=>x.roas!=null&&x.ctr!=null).map(x=>({label:x.name,x:$('#bubbleX').value==='ctr'?x.ctr:x.v[3],y:x.roas,size:x.v[0],color:palette[x.brand]})),{label:'素材成效氣泡圖',xLabel:$('#bubbleX').value==='ctr'?'連結 CTR':'歸因購買次數',yLabel:'Meta ROAS',xFmt:$('#bubbleX').value==='ctr'?v=>pct(v,2):v=>fmt(v,0),yFmt:v=>fmt(v,1)+'×',detailsId:'creativeDetail',legendItems:all().map(k=>[shortBrand(k),palette[k]]),foot:'氣泡面積代表花費，點選顯示原始數值；與下方表格同步篩選。ROAS 為平台歸因，不等於整體 ROI。極小氣泡保留最小可點擊尺寸。'});$('#adTable').innerHTML=`<p class="small">${filtered.length} 組同名廣告 / 花費 NT$ ${fmt(sum(filtered.map(x=>x.v[0])))}</p>`+table(['廣告名稱','品牌','訴求','花費','曝光','連結CTR','購買','購買價值','ROAS','CPA'],filtered.map(x=>[esc(x.name),B[x.brand].name,esc(x.tag),fmt(x.v[0]),fmt(x.v[1]),pct(x.ctr,2),fmt(x.v[3]),fmt(x.v[4]),fmt(x.roas,2),fmt(x.cpa)]));let groups={};for(let x of a){let z=groups[x.tag]??=[0,0,0,0,0];x.v.forEach((v,i)=>z[i]+=v)}$('#tagTable').innerHTML=horizontal(Object.entries(groups).sort((a,b)=>b[1][0]-a[1][0]).map(([k,v])=>({label:k,value:v[0]})),{label:'訴求分類花費',format:v=>'NT$ '+fmt(v)})+table(['名稱分類','花費','花費占比','購買','購買價值','ROAS','CPA'],Object.entries(groups).sort((a,b)=>b[1][0]-a[1][0]).map(([k,v])=>[esc(k),fmt(v[0]),pct(v[0]/sum(a.map(x=>x.v[0]))),fmt(v[3]),fmt(v[4]),fmt(div(v[4],v[0]),2),fmt(div(v[0],v[3]))]))}

function audience(){let ks=all();return page(5,card('新客訂單同比',columns(ks.map(k=>({label:shortBrand(k),values:[per(k,'yoy').s[5],per(k).s[5]]})),[['2025 同期','var(--series-prev)'],['2026 雙11','var(--accent)']],{label:'新客訂單同比柱狀圖',format:v=>fmt(v),foot:'新客訂單非去重後顧客人數。'}))+card('新舊客淨營收占比',ks.map(k=>{let s=per(k).s,a=s[6]/s[4],b=s[8]/s[4];return `<div class="mixrow"><b>${shortBrand(k)}</b><div class="mixbar"><span style="width:${a*100}%">${pct(a,1)}</span><span style="width:${b*100}%">${pct(b,1)}</span></div></div>`}).join('')+legend([['新客','var(--accent)'],['舊客','var(--series-prev)']]))+card('新舊客訂單與營收' ,table(['品牌／期間','新客訂單','新客訂單占比','新客淨營收','新客淨客單','舊客訂單','舊客淨營收','已記錄花費／新客訂單'],ks.flatMap(k=>['now',comp()].map(p=>{let s=per(k,p).s;return[B[k].name+' / '+(p==='now'?'本期':compareName()),fmt(s[5]),pct(div(s[5],s[0])),fmt(s[6]),fmt(div(s[6],s[5])),fmt(s[7]),fmt(s[8]),fmt(div(spend(per(k,p)),s[5]))]})))+note('新客訂單不等同不重複新客人數；花費／新客訂單不等同廣告歸因 CAC。Dashboard新舊客訂單與Shopify原生顧客數不強制相等。'))+card('Meta 受眾年齡與性別',`<div class="controls"><label>性別 <select id="sex"><option value="ALL">全部</option><option value="female">女性</option><option value="male">男性</option><option value="unknown">不明</option></select></label><label>年齡 <select id="age"><option value="ALL">全部</option>${['18-24','25-34','35-44','45-54','55-64','65+','Unknown'].map(x=>`<option>${x}</option>`).join('')}</select></label></div><div id="audChart"></div><div id="audTable"></div><p class="small">僅本期年齡與性別交叉資料；分組小額四捨五入可能造成 1–2 元差異。版位細分尚未納入。</p>`)+card('新客策略觀察',ks.map(k=>ins(B[k].name,({'DS':'新客訂單 303，去年 344，舊客訂單 291 高於去年 266。淨營收成長尚未反映新客擴張。','ASH':'新客訂單由去年 103 增至 366，成長明顯，但仍須辨別新客商品價值與購買來源。','CA':'新客訂單 7，去年 98；銷售缺列已確認為零交易日，優先評估可購買商品型號與規格，再調整新客導購策略。','2XU':'新客訂單 255，去年 120，成長 112.5%；舊客訂單亦增加，屬雙向成長。'})[k])).join('')))}function audUpdate(){let sex=$('#sex').value,age=$('#age').value,a=all().flatMap(k=>B[k].audience.map(r=>({...r,k}))).filter(x=>(sex==='ALL'||x.sex===sex)&&(age==='ALL'||x.age===age)).sort((a,b)=>b.v[0]-a.v[0]);let ages=['18-24','25-34','35-44','45-54','55-64','65+','Unknown'].filter(t=>a.some(z=>z.age===t));$('#audChart').innerHTML=columns(ages.map(t=>({label:t,values:['male','female','unknown'].map(s=>sum(a.filter(z=>z.age===t&&z.sex===s).map(z=>z.v[3])))})),[['男性','var(--accent)'],['女性','var(--series-4)'],['不明','var(--series-prev)']],{label:'年齡與性別歸因購買',format:v=>fmt(v),foot:'歸因購買事件，非去重人數；與品牌、性別、年齡篩選同步。'});$('#audTable').innerHTML=table(['品牌','年齡','性別','花費','曝光','連結點擊','購買','ROAS','CPA'],a.map(x=>[B[x.k].name,x.age,({'female':'女性','male':'男性','unknown':'不明'})[x.sex],fmt(x.v[0]),fmt(x.v[1]),fmt(x.v[2]),fmt(x.v[3]),fmt(div(x.v[4],x.v[0]),2),fmt(div(x.v[0],x.v[3]))]))}

const productText={DS:['原始目的：新品推廣及客單價提升','規劃 AOV 5,920 → 6,500，實際淨客單 7,448（口徑不同，不能直接認定 AOV 達標）。兩份規劃折扣描述有差異，須查商品成交價。外套與長袖上衣合計190.9萬（43.1%），建議以秋冬穿搭與機能測試商品組合。商品名稱有11.11限時獨家者列入排名，但未取得完整新品季別標籤，不能推算全部新品占比。'],ASH:['原始目的：新品銷售與顧客轉移','實際店內商品銷售可按 Vendor 檢視，Callaway 與 G/FORE、PAYNTR 為前三。無跨店客戶識別，不能證明 G/FORE 顧客轉移；亦不可把 ASH 店內 Callaway 銷售歸入 Callaway 獨立站。'],CA:['原始目的：球桿出清','原規劃商品年份與出清目的有差異。QUANTUM MAX及D款淨營收合計113,569元（74.4%）；ELYTE三款38,075元。無歷史庫存與商品年份對照，不能判斷出清率。須比對兩年可購買型號數、規格SKU、價格帶及廣告導購頁選擇；成交商品清單不代表完整可售SKU。'], '2XU':['原始目的：熱銷壓縮補貨與提升 CVR','規劃0.52%→0.60%；本期台灣CVR 0.864%，達標。一般服飾淨營收52.2%，壓縮服飾30.6%，三鐵10.8%。限時單一價11/6–13與實際廣告曝光一致；無庫存資料不能判定補貨成效。']};function product(){return page(6,all().map(k=>{let b=B[k],s=per(k).s;let t=(rows,label)=>table([label,'台灣淨營收','淨售出件數','占品牌淨營收'],rows.map(x=>[esc(x[0]),fmt(x[1],2),fmt(x[2]),pct(div(x[1],s[4]))]));return card(b.name,ins(...productText[k])+horizontal((b.vendors||b.types||b.products||[]).slice(0,6).filter(x=>x[1]>0).map(x=>({label:x[0],value:x[1]})),{label:b.vendors?'商品品牌淨營收':b.types?'品類淨營收':'商品淨營收',format:v=>'NT$ '+fmt(v),foot:'前六名正淨營收項目，完整資料見下表。'})+(b.vendors?t(b.vendors,'商品品牌（Vendor）'):'')+(b.types?'<h4>品類銷售</h4>'+t(b.types,'品類'):'')+(b.products?'<details open><summary>商品名稱排名（依淨營收，最多30項）</summary>'+t(b.products,'商品名稱')+'</details>':'')+(b.shopify_totals?'<p class="small">本期淨售出件數 '+fmt(b.shopify_totals.now[4])+'；每單淨件數 '+fmt(div(b.shopify_totals.now[4],s[0]),2)+'（包含退貨影響）。</p>':'<p class="small">ASH 商品僅 Vendor 層級，尚未取得單品排名。</p>'))}).join('')+(all().some(k=>k==='ASH'||k==='CA')?card('Callaway 跨站商品營收',horizontal([{label:'ASH GOLF 站內 Callaway Vendor',value:B.ASH.vendors.find(x=>x[0]==='Callaway')[1]},{label:'Callaway 獨立官網全站',value:per('CA').s[4]}],{label:'Callaway 跨站比較',format:v=>'NT$ '+fmt(v),foot:'不同站點與商品範圍，不可直接合併歸因；無法證明需求轉移。'})):'')+card('折扣與退貨影響｜兩年同期',table(['品牌','去年折扣率','本次折扣率','去年退貨金額率','本次退貨金額率'],all().map(k=>{let a=per(k).s,b=per(k,'yoy').s;return [B[k].name,pct(div(-b[2],b[1])),pct(div(-a[2],a[1])),pct(div(-b[3],b[1]+b[2])),pct(div(-a[3],a[1]+a[2]))]}))+note('折扣率不含商品直接變價；退貨金額率按入帳期間計算，並非同一批訂單的退貨率。'))+note('毛利及庫存依使用者指示不提供；商品名稱可能包含多SKU，商品排行榜不等同SKU層級 ROAS。產品表為實際 Shopify 資料，不可與 Meta 歸因直接合併。'))}

const actions={DS:[['P1','維持 ROI 下限、重分正檔花費','依11/18實際倒數起始日重新計算階段效率；測試新品目錄與換季情境。','廣告投放','品牌 ROI ≥ 6.30，並觀察淨營收是否維持。'],['P2','驗證新品與淨客單','拆分 Sport / Golf、新品 / 過季及退貨。','企劃＋電商','實際 AOV、商品淨營收與退貨率。']],ASH:[['P1','提高客單與商品價值','站內 CVR 改善，但淨客單下降；測試球具、搭配商品與高客單組合導購。','企劃＋投放','ROI ≥ 9.00；淨客單、實際訂單同步。'],['P2','保留高效率素材','目錄、Callaway 素材及倒數的高 ROAS 作為候選；測試相同受眾下的商品組與 LP。','廣告投放','等條件下 ROAS、CPA 與實際 ROI。']],CA:[['P0','排查網站購買阻力及追蹤','12天零訂單、零淨營收已確認。優先檢查加購至結帳（13.4% vs 前期40.0%）、商品規格／價格、運費、付款、Meta Pixel/CAPI。','電商＋投放','實際CVR、加購至結帳率、可購買商品規格、追蹤事件一致性。'],['P1','依商品選擇與需求修正導購及訴求','盤點可購買型號、桿身硬度、角度、慣用手與價格帶；拆分2026新桿與出清款，按需求匹配調整投放。','企劃＋廣告投放','ROI 朝 16.70 改善；購買／點擊事件比率及 Shopify 訂單。']], '2XU':[['P1','保留拓新，改善倒數期','主 BN、服飾折扣素材延續，重新測試倒數期商品與利益點。','廣告投放','ROI ≥ 7.16；新客訂單、實際網站 CVR。'],['P2','評估 Google 與 Meta 分工','Google ROAS 9.70 但存在跨媒體歸因重疊；先做分段預算測試。','廣告投放','整體 ROI、總淨營收，不加總兩平台歸因營收。']]};function action(){return page(7,all().map(k=>card(B[k].name,actions[k].map(a=>`<div class="action"><span class="pill">${a[0]}</span> <b>${a[1]}</b><p>${a[2]}</p><div class="small">負責：${a[3]}<br>驗收：${a[4]}</div></div>`).join(''))).join('')+card('8.3 目標 ROI 情境試算',`<div class="controls"><label>假設營收成長 <input id="scenario" type="range" min="-20" max="50" step="5" value="0"><b id="scenarioValue">0%</b></label></div><div id="scenarioChart"></div><div id="scenarioTable"></div>`+note('目標效率下可承擔花費 = 本次淨營收 ×（1 + 假設成長率）÷ 目標 ROI。這是數學情境試算，不是預算建議；不能保證減少花費後營收不變。'))+note('本報告只提供決策建議，未變更任何廣告、預算或店舖。目標 ROI 不是單一素材 ROAS 的門檻。'))}

function scenarioUpdate(){let v=Number($('#scenario').value);$('#scenarioValue').textContent=(v>0?'+':'')+v+'%';$('#scenarioChart').innerHTML=columns(all().map(k=>({label:shortBrand(k),values:[spend(per(k)),per(k).s[4]*(1+v/100)/B[k].target]})),[['本次花費','var(--accent)'],['情境可承擔花費','var(--series-4)']],{label:'目標 ROI 情境花費比較',foot:'NT$；情境試算，不代表實際營收預測。'});$('#scenarioTable').innerHTML=table(['品牌','本次已記錄花費','目標效率下可承擔花費','差額'],all().map(k=>{let b=B[k],p=per(k),cap=p.s[4]*(1+v/100)/b.target,d=cap-spend(p);return[b.name,fmt(spend(p)),fmt(cap),`<span class="${d>=0?'good':'bad'}">${d>=0?'+':''}${fmt(d)}</span>`]}))}

function audit(){return page(8,card('資料範圍',table(['品牌','本期','活動前比較','去年同期','Meta 帳戶'],all().map(k=>{let b=B[k];return[b.name,b.start+'–'+b.end,b.pre+'–'+b.preend,b.start.replace('2026','2025')+'–2025-11-22',b.id]}))+'<p>去年活動規劃留空，採同日曆區間比較。前期包含會員搶先購，不是純無促銷對照；搶先購不投放雙11活動廣告。所有金額 TWD、台灣市場限定。</p>')+card('數據追溯與對帳明細',`<details><summary>展開 Shopify / Dashboard 銷售原始對照</summary>${table(['品牌','期間','Shopify 淨營收','Dashboard 淨營收','差額','Shopify 訂單','Dashboard 訂單','差額'],all().flatMap(k=>['now','prev','yoy'].map(p=>{let x=B[k].shopify_totals?.[p],q=per(k,p);return [B[k].name,({now:'2026雙11',prev:'活動前',yoy:'2025同期'})[p],x?fmt(x[0],2):'未直接核對',fmt(q.s[4],2),x?fmt(x[0]-q.s[4],2):'—',x?fmt(x[1]):'未直接核對',fmt(q.s[0]),x?fmt(x[1]-q.s[0]):'—']})))}</details><details><summary>展開2026每日與彙總數字對照</summary>${table(['品牌','每日淨營收加總','期間淨營收','差額','每日Meta加總','帳戶Meta','差額','素材花費加總','每日Google加總','期間Google'],all().map(k=>{let b=B[k],p=per(k),n=sum(b.daily.map(x=>x.net)),m=sum(b.daily.map(x=>x.meta)),g=sum(b.daily.map(x=>x.google)),a=sum(b.ads.map(x=>x.v[0]));return [b.name,fmt(n,2),fmt(p.s[4],2),fmt(n-p.s[4],2),fmt(m,2),fmt(p.m[0],2),fmt(m-p.m[0],2),fmt(a,2),p.g?fmt(g,2):'無列',p.g?fmt(p.g[0],2):'無列']}))}<p class="small">每日及彙總為既有快照內部一致性核對，不等於獨立源系統驗證。Meta ASH 連結點擊及購買價值、2XU 購買價值分組和帳戶有1單位差異，採帳戶層級。</p></details><details><summary>展開2025 Google Ads 人工提供紀錄</summary>${table(['品牌','期間','總花費 TWD','來源','獨立對帳'],all().map(k=>{let x=D.manual_inputs.google_2025_spend.values[k];return [B[k].name,x.start+'–'+x.end,fmt(x.cost,2),'使用者 2026/11/25 提供','未核對']}))}<p class="small">只採花費，不提供2025 Google 轉換次數、價值、CPA、ROAS；未提供逐日拆分。</p></details>` )+card('資料來源',`<p>Meta Ads MCP：四帳戶，Country=TW；帳戶每日數據及名稱／年齡性別 breakdown。2XU Taiwan（${B['2XU'].id}），不含 HK。</p><p><a class="source" href="${D.sources.dashboard}" target="_blank" rel="noopener noreferrer">Dashboard 原始試算表</a> · <a href="${D.sources.dashboard_app}" target="_blank" rel="noopener noreferrer">既有 Dashboard</a></p><p>品牌銷售表 DESCENTE / ASH GOLF / Callaway / 2XU TW，Google gads_by brand_contry，Meta metaads_by_brand_contry。廣告歷史表從 2026/1/1 起。</p><p>Shopify：四品牌台灣 Billing country / Session country，淨營收與訂單均與 Dashboard 一致（ASH本期；其餘三品牌三期）。Callaway逐日零值已核對。直接取得之去重顧客數與Dashboard新舊客訂單為不同口徑。</p><p><a href="${D.sources.plan}" target="_blank" rel="noopener noreferrer">EC 活動規劃</a> · <a href="${D.sources.plan2}" target="_blank" rel="noopener noreferrer">雙11專案規劃</a></p>`)+card('公式與限制','<p>ROI = Shopify 淨營收 / (Meta + Google 已記錄花費)；Meta ROAS = 平台購買價值 / Meta 花費；CPA = Meta 花費 / 平台購買事件；CTR = 連結點擊 / 曝光；淨客單 = 淨營收 / 實際訂單；比率採總分子除總分母。</p>'+note('2025 Google 期間花費已由使用者提供，未獨立對帳，轉換定義不一致故不比較 Google 轉換指標。ASH、Callaway Google 本期／前期無列；2XU 前期 Google 僅 15/21 天有列。ROI 採已記錄花費暫算。Callaway 原始缺列12天已由 Shopify TIMESERIES 驗證為0。DESCENTE 倒數實際曝光起日11/18，已修正階段切分。')+'<p>四站 Shopify Taiwan Sessions 已直接驗證；已取得 DS、CA、2XU 商品名稱及部分品類，ASH Vendor。跨店客戶識別、完整素材原圖／全部文案、版位明細、商品季別仍未完整。歷史可購買SKU數未提供，SKU豐富度為假設。未提供重大事件及毛利庫存，無法證明成因、獲利或增量效果。報告不虛構缺失資料。</p>'))}

/* Chapter 10: exploratory market association. All results computed from paired snapshot rows. */
const marketKeys=['ALL',...keys], marketLabel=k=>k==='ALL'?'四品牌合計':B[k].name;
const avg=a=>sum(a)/a.length;
function marketCorr(a,b){let ma=avg(a),mb=avg(b),den=Math.sqrt(sum(a.map(x=>(x-ma)**2))*sum(b.map(x=>(x-mb)**2)));return den?sum(a.map((x,i)=>(x-ma)*(b[i]-mb)))/den:null}
function marketResidual(y,cols){let basis=[];for(let z of cols){let v=z.slice();for(let q of basis){let dot=sum(v.map((x,i)=>x*q[i]));v=v.map((x,i)=>x-dot*q[i])}let norm=Math.hypot(...v);if(norm>1e-9)basis.push(v.map(x=>x/norm))}let v=y.slice();for(let q of basis){let dot=sum(v.map((x,i)=>x*q[i]));v=v.map((x,i)=>x-dot*q[i])}return v}
function marketRows(k){let ks=k==='ALL'?keys:[k];return D.market.rows.map(r=>{let daily=ks.map(k=>B[k].daily.find(x=>x.date===r.date));let next=new Date(r.date+'T00:00:00Z');next.setUTCDate(next.getUTCDate()+1);let nextDate=next.toISOString().slice(0,10);return {...r,net:sum(daily.map(x=>x.net)),spend:sum(daily.map(x=>x.meta+(x.google??0))),lag:sum(ks.map(k=>B[k].daily.find(x=>x.date===nextDate).net))}})}
function marketStats(k){let a=marketRows(k),x=a.map(r=>r.return_pct),y=a.map(r=>r.net),e=a.filter(r=>r.date!=='2026-11-11'),z=[a.map(()=>1),a.map(r=>r.spend),a.map(r=>+(r.date==='2026-11-11')),a.map(r=>+(r.date>='2026-11-16'))];return {k,raw:marketCorr(x,y),lag:marketCorr(x,a.map(r=>r.lag)),exclude:marketCorr(e.map(r=>r.return_pct),e.map(r=>r.net)),adjust:marketCorr(marketResidual(x,z),marketResidual(y,z)),up:avg(a.filter(r=>r.return_pct>0).map(r=>r.net)),down:avg(a.filter(r=>r.return_pct<0).map(r=>r.net))}}
function marketPage(){let stats=marketKeys.map(marketStats),total=stats[0],brand=$('#brand').value;return page(9,
ins('結論｜觀察到正相關，但未證實獨立影響','<p>台股上漲日四品牌平均淨營收較下跌日高 '+pct(change(total.up,total.down))+'。控制已記錄廣告花費、11/11及後段檔期後，各品牌均未達一般統計顯著門檻。不能將營收衰退直接歸因於股市。</p>')+
'<div class="kpis">'+kpi('上漲日平均總營收','NT$ '+fmt(total.up),'5個交易日')+kpi('下跌日平均總營收','NT$ '+fmt(total.down),'10個交易日')+kpi('平均營收差異',diff(change(total.up,total.down)),'未控制其他因素')+'</div>'+
card('01｜上漲與下跌日營收比較',columns(stats.slice(1).map(s=>({label:shortBrand(s.k),values:[s.up,s.down]})),[['上漲日','var(--red)'],['下跌日','var(--green)']],{label:'各品牌上漲及下跌日平均淨營收',format:compact,foot:'TWD；上漲5天、下跌10天。紅漲綠跌採台股慣例。'})+table(['品牌','上漲日平均淨營收','下跌日平均淨營收','差異'],stats.map(s=>[marketLabel(s.k),fmt(s.up),fmt(s.down),diff(change(s.up,s.down))])))+
card('02｜每日台股漲跌與 Shopify 淨營收','<div class="toolbar"><label>品牌 <select id="marketBrand">'+marketKeys.map(k=>'<option value="'+k+'" '+(brand===k?'selected':'')+'>'+marketLabel(k)+'</option>').join('')+'</select></label><label>日期 <input id="marketDay" type="range" min="0" max="14" value="7" step="1"></label></div><div id="marketTrend"></div><div id="marketDetail" class="chart-detail" aria-live="polite"></div>')+
card('03｜相關係數與敏感度驗證',columns(stats.map(s=>({label:s.k==='ALL'?'合計':shortBrand(s.k),values:[s.raw,s.exclude,s.adjust]})),[['原始相關','var(--accent)'],['排除11/11','var(--series-2)'],['控制干擾後','var(--series-3)']],{label:'Pearson相關係數及偏相關',format:v=>fmt(v,3),foot:'係數介於 −1 與 +1；接近0表示線性關聯較弱。'} )+table(['品牌','當日 r','隔日 r','排除11/11 r','控制干擾後 r'],stats.map(s=>[marketLabel(s.k),fmt(s.raw,3),fmt(s.lag,3),fmt(s.exclude,3),fmt(s.adjust,3)]))+'<p>原始 Pearson 相關：2XU（r=0.628，p≈0.012）及合計（r=0.609，p≈0.016）達一般未校正顯著門檻。控制三項因素後，所有品牌均未達 p&lt;0.05；2XU 方向反轉，反映結果對控制方式敏感。樣本僅15日，不能據此認定負向因果效果。</p>')+
card('04｜可能的財富效果與下一步','<p>股價下跌可能使資產持有人延後非必要消費；這是待驗證假設，並非本次已證明的消費行為。</p>'+table(['品牌','後續驗證假設'],[['DESCENTE','高單價機能服飾購買延後'],['ASH GOLF','精品球具與服飾消費意願下降'],['Callaway','高單價球桿決策延後；訂單樣本少'],['2XU TW','專業運動裝備支出受消費信心影響']])+'<p>建議以6至12個月資料，追蹤每日淨營收、流量、CVR、客單價、訂單、Meta/Google 花費、促銷力度、星期、發薪日、假日、可售 SKU 及缺貨率，並加入近5日累計股市報酬。優先檢查 CVR 與客單價，區分購買意願及金額變化。</p>')+
card('05｜資料來源與計算限制','<p>'+esc(D.market.source)+'；Shopify 淨營收取自既有每日快照，台灣市場、TWD。只使用11/02至11/20的15個交易日；週末不填虛構股價。隔日採下一日曆日。控制變數為已記錄廣告花費、11/11指標及11/16起後段檔期指標；ASH、Callaway Google無列，暫用已記錄花費。偏相關為兩組變數分別對控制項線性殘差後之 Pearson r。多重比較未校正；不代表因果關係。</p><details><summary>展開配對原始資料</summary>'+table(['日期','台股收盤','漲跌幅','DESCENTE','ASH GOLF','Callaway','2XU','四品牌合計'],D.market.rows.map((r,i)=>[r.date,fmt(r.close,2),fmt(r.return_pct,2)+'%',...keys.map(k=>fmt(marketRows(k)[i].net,2)),fmt(marketRows('ALL')[i].net,2)]))+'</details>'))}
function marketUpdate(){let k=$('#marketBrand').value,idx=+$('#marketDay').value,a=marketRows(k),max=Math.max(1,...a.map(r=>r.net)),min=Math.min(0,...a.map(r=>r.net)),L=70,R=735,w=R-L,x=i=>L+i*w/14,y=v=>120-(v-min)/(max-min)*90,z=v=>207-v*8.6;let g='<rect x="'+(x(idx)-12)+'" y="15" width="24" height="253" fill="var(--series-prev)" opacity=".25"/><text x="70" y="15" class="axis-title">Shopify 淨營收（NT$）</text>';for(let i=0;i<=4;i++){let v=min+(max-min)*i/4;g+='<line x1="'+L+'" x2="'+R+'" y1="'+y(v)+'" y2="'+y(v)+'" class="gridline"/><text x="62" y="'+(y(v)+4)+'" text-anchor="end" class="axis">'+compact(v)+'</text>'}g+='<polyline points="'+a.map((r,i)=>x(i)+','+y(r.net)).join(' ')+'" fill="none" stroke="var(--accent)" stroke-width="2.2"/><text x="70" y="145" class="axis-title">台股每日漲跌幅</text><line x1="'+L+'" x2="'+R+'" y1="207" y2="207" class="baseline"/>';for(let v of [-6,-3,0,3,6])g+='<text x="62" y="'+(z(v)+4)+'" class="axis" text-anchor="end">'+v+'%</text>';a.forEach((r,i)=>{g+='<circle class="chart-mark" cx="'+x(i)+'" cy="'+y(r.net)+'" r="'+(i===idx?5:3)+'" fill="var(--accent)"><title>'+r.date+' NT$ '+fmt(r.net,2)+'</title></circle><rect class="chart-mark" x="'+(x(i)-9)+'" y="'+Math.min(z(r.return_pct),207)+'" width="18" height="'+Math.abs(r.return_pct)*8.6+'" fill="'+(r.return_pct>=0?'var(--red)':'var(--green)')+'"><title>'+r.date+' '+r.return_pct+'%</title></rect><text x="'+x(i)+'" y="283" class="axis" text-anchor="middle">'+r.date.slice(5)+'</text>'});$('#marketTrend').innerHTML=legend([['淨營收','var(--accent)'],['台股上漲','var(--red)'],['台股下跌','var(--green)']])+chartFrame(g,'每日營收與台股漲跌共用日期軸','兩個獨立尺度，僅交易日。',true);let r=a[idx];$('#marketDetail').textContent=r.date+'｜'+marketLabel(k)+'｜台股 '+(r.return_pct>0?'+':'')+fmt(r.return_pct,2)+'%｜淨營收 NT$ '+fmt(r.net,2)}

const fns=[rev,budget,pace,funnel,creative,audience,product,action,audit,marketPage];function show(i){active=i;document.querySelectorAll('.section').forEach((s,j)=>s.classList.toggle('active',j===i));document.querySelectorAll('#nav a').forEach((s,j)=>s.classList.toggle('active',j===i));$('#period').disabled=(i===3||i===9);window.scrollTo({top:0,behavior:'instant'})}function render(){let ks=all();$('#period').disabled=(active===3||active===9);$('#scope').textContent=ks.length===4?'10/30–11/22（依品牌起始日）':B[ks[0]].start.slice(5)+'–11/22 · '+B[ks[0]].days+' 天';$('#content').innerHTML=fns.map(f=>f()).join('');$('#nav').innerHTML=navs.map((n,i)=>`<a href="#s${i}" class="${i===active?'active':''}" data-i="${i}">${String(i+1).padStart(2,'0')}　${n}</a>`).join('');$('#nav').querySelectorAll('a').forEach(a=>a.onclick=e=>{e.preventDefault();show(+a.dataset.i)});['from','to'].forEach(id=>$('#'+id).onchange=trendUpdate);['tag','sort','minsp','bubbleX'].forEach(id=>$('#'+id).onchange=adUpdate);$('#search').oninput=adUpdate;['age','sex'].forEach(id=>$('#'+id).onchange=audUpdate);$('#scenario').oninput=scenarioUpdate;$('#metaMode').onchange=metaUpdate;$('#metaChartMetric').onchange=metaChartUpdate;$('#funnelBrand').onchange=funnelUpdate;$('#funnelYear').onchange=funnelUpdate;trendUpdate();adUpdate();audUpdate();metaUpdate();funnelUpdate();scenarioUpdate();$('#marketBrand').onchange=marketUpdate;$('#marketDay').oninput=marketUpdate;marketUpdate();['metaMode','funnelYear','metaChartMetric','bubbleX'].forEach(segmented)}
function dl(){let ks=all(),rows=[['brand','period','start','end','net_sales','orders','meta_spend','google_recorded_spend','ROI_recorded','meta_purchase_value','meta_ROAS','meta_purchases','new_orders','old_orders']];for(let k of ks){let b=B[k];for(let p of ['now','prev','yoy']){let a=per(k,p);rows.push([b.name,p,p==='now'?b.start:p==='prev'?b.pre:b.start.replace('2026','2025'),p==='now'?b.end:p==='prev'?b.preend:'2025-11-22',a.s[4],a.s[0],a.m[0],a.g?.[0]??'',roi(a),a.m[7],roas(a),a.m[6],a.s[5],a.s[7]])}}let c='\ufeff'+rows.map(r=>r.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\r\n'),u=URL.createObjectURL(new Blob([c],{type:'text/csv;charset=utf-8'}));let a=document.createElement('a');a.href=u;a.download='EMERS_1111_'+$('#brand').value+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}$('#brand').onchange=render;$('#period').onchange=render;$('#export').onclick=dl;$('#print').onclick=()=>window.print();$('#raw').onclick=()=>{let u=URL.createObjectURL(new Blob([JSON.stringify(D,null,2)],{type:'application/json'}));let a=document.createElement('a');a.href=u;a.download='EMERS_1111_2026_snapshot_v3.4.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};document.addEventListener('click',e=>{let b=e.target.closest('[data-detail]');if(b&&$('#'+b.dataset.target))$('#'+b.dataset.target).textContent=b.dataset.detail});document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-detail]')){e.preventDefault();$('#'+e.target.dataset.target).textContent=e.target.dataset.detail}});render();
